css:
.loader { display: flex; flex-direction: column; gap: calc(var(--loader-size) * .035); width: var(--loader-size); animation: twPulse calc(var(--loader-speed) * 1.8) cubic-bezier(.4, 0, .6, 1) infinite; }
.loader .label { width: 34%; height: calc(var(--loader-size) * .04); border-radius: 9999px; background: color-mix(in srgb, var(--loader-color) 32%, transparent); }
.loader .label.wide { width: 48%; }
.loader .field { height: calc(var(--loader-size) * .11); margin-bottom: calc(var(--loader-size) * .025); border-radius: calc(var(--loader-size) * .025); background: color-mix(in srgb, var(--loader-color) 14%, transparent); border: calc(var(--loader-size) * .008) solid color-mix(in srgb, var(--loader-color) 26%, transparent); box-sizing: border-box; }
.loader .btn { width: 40%; height: calc(var(--loader-size) * .095); margin-top: calc(var(--loader-size) * .02); border-radius: 9999px; background: var(--loader-color); }
@keyframes twPulse { 50% { opacity: .5; } }
